SELECT CASE WHEN budget >= 4093000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, COUNT_IF(location = 'Chiang Mai') AS chiang_mai_events, COUNT_IF(dept_name = 'Sales') AS sales_events, SORT_ARRAY(COLLECT_SET(location)) AS location_list, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN location = 'London' THEN 1 END), 0), 2) AS budget_per_london FROM departments GROUP BY CASE WHEN budget >= 4093000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY sales_events DESC;
